head.script:
scwin.screenId = "jldfil30407";

///////// 1. 변수 및 선언 영역 /////////

scwin.applDd = undefined;

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.result = undefined;


///////// 2. 초기화 영역 /////////

// 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님). 진입점 선두 단계.
/**
 * @method
 * @name scwin.init_nowVars
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_calndDd", fn: function(){ return ((dma_result.get("calndDd") ?? (() => { throw new Error("unresolved:" + "result.calndDd"); })()) !== '' && !(String(((dma_result.get("calndDd") ?? (() => { throw new Error("unresolved:" + "result.calndDd"); })())) == null ? '' : ((dma_result.get("calndDd") ?? (() => { throw new Error("unresolved:" + "result.calndDd"); })()))).length === 0)); } }, { id: "c_when_91_txt", fn: function(){ return ((dma_result.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "result.reservStatTpCd"); })()) === '0'); } }, { id: "c_when_92_txt", fn: function(){ return ((dma_result.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "result.reservStatTpCd"); })()) === '1'); } }, { id: "c_when_93_txt", fn: function(){ return ((dma_result.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "result.reservStatTpCd"); })()) === '2'); } }, { id: "c_when_94_txt", fn: function(){ return ((dma_result.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "result.reservStatTpCd"); })()) === '3'); } }, { id: "c_when_95_txt", fn: function(){ return ((dma_result.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "result.reservStatTpCd"); })()) === '4'); } }, { id: "c_when_96_txt", fn: function(){ return ((dma_result.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "result.reservStatTpCd"); })()) === '5'); } }, { id: "if_applNo", fn: function(){ return ((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })()) !== '' && !(String(((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })())) == null ? '' : ((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })()))).length === 0)); } }, { id: "tr_87", fn: function(){ return ((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })()) !== '' && !(String(((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })())) == null ? '' : ((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })()))).length === 0)); } }, { id: "btn_tempRegister", fn: function(){ return ((dma_result.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "result.reservStatTpCd"); })()) === '0'); } }, { id: "btn_register", fn: function(){ return ((dma_result.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "result.reservStatTpCd"); })()) === '0'); } }, { id: "btn_cancel", fn: function(){ return ((dma_result.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "result.reservStatTpCd"); })()) === '0'); } }, { id: "btn_register_2", fn: function(){ return ((dma_result.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "result.reservStatTpCd"); })()) === '1'); } }, { id: "btn_cancel_2", fn: function(){ return ((dma_result.get("reservStatTpCd") ?? (() => { throw new Error("unresolved:" + "result.reservStatTpCd"); })()) === '1'); } }, { id: "if_today", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "today" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("today")) < ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.applDd !== "undefined" && scwin.applDd !== null ? scwin.applDd : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "applDd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("applDd"))); } }, { id: "if_today", fn: function(){ return ((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })()) !== '' && !(String(((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })())) == null ? '' : ((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })()))).length === 0)); } }, { id: "c_otherwise_111", fn: function(){ return (!(((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })()) !== '' && !(String(((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })())) == null ? '' : ((dma_result.get("applNo") ?? (() => { throw new Error("unresolved:" + "result.applNo"); })()))).length === 0)))); } }, { id: "if_today_2", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "today" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("today")) < ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.applDd !== "undefined" && scwin.applDd !== null ? scwin.applDd : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "applDd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("applDd"))); } }, { id: "c_when_182_txt", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "corpUsrTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("corpUsrTpCd")) === '11'); } }, { id: "c_when_183_txt", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "corpUsrTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("corpUsrTpCd")) === '21'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_year", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("year"))); } },
        { childId: "ipt_month", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("month"))); } },
        { childId: "__rb0", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("comNm")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.fn_confroomChangeState();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30407.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil30407.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

