/**
 * @method
 * @name scwin.colorSetting
 * @author Inswave
 * @date 2026. 09. 29
 * @param eltId result
 * @returns
 * @hidden N
*/
scwin.colorSetting = function (eltId, result) {
    /* sdd-asis-lifecycle:begin fn_colorSetting — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (result === 'PRE') {
        $('#' + eltId).css('backgroundColor', '');
    } else {
        if (result === 'ING') {
            $('#' + eltId).css('backgroundColor', 'blue');
        } else {
            if (result === 'PST') {
                $('#' + eltId).css('backgroundColor', 'red');
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


