/**
 * @method
 * @name scwin.isNumber
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj
 * @returns
 * @hidden N
*/
scwin.isNumber = function (_obj) {
    /* sdd-asis-lifecycle:begin fn_IsNumber — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    str = scwin.ignoreSpaces(_obj.value);
    for(i=0;i<str.length;i++){
        if (isNaN(str.substr(i,1)) === true){
            _obj.select();
            return false;
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.isNull
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj _msg
 * @returns
 * @hidden N
*/
scwin.isNull = async function (_obj, _msg) {
    /* sdd-asis-lifecycle:begin fn_IsNull — as-is 원문 본문(전환 이관 · 포팅 적용됨) */


    if(scwin.trim(_obj.value) === ''){
        await $c.win.alert("'" + _msg + "' 항목을 입력하세요");
        _obj.focus();
        return true;
    }
    return false;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.ignoreSpaces
 * @author Inswave
 * @date 2026. 09. 29
 * @param _str
 * @returns
 * @hidden N
*/
scwin.ignoreSpaces = function (_str) {
    /* sdd-asis-lifecycle:begin fn_IgnoreSpaces — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    return _str.replace(/\s/g, "");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.trim
 * @author Inswave
 * @date 2026. 09. 29
 * @param _str
 * @returns
 * @hidden N
*/
scwin.trim = function (_str) {
    /* sdd-asis-lifecycle:begin fn_Trim — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    if(typeof(_str)!=='undefined') return _str.replace(/^\s{1,}/, "").replace(/\s{1,}$/, "");
    else return _str;
    /* sdd-asis-lifecycle:end */
};


